saved=[]
class M(type):
 def __new__(meta,name,bases,ns):
  saved.append(ns)
  return type.__new__(meta,name,bases,ns)
class C(metaclass=M):
 ns=locals()
 value=7
print(saved[-1] is C.ns,C.value)

